using System;
using UnityEngine;

/// <summary>
/// Everything the game needs from the project: shaders, audio, and the 3D props of each theme.
/// Generated by Tools > Black Hole > Rebuild Catalog (Assets/Editor/CatalogBuilder.cs).
/// </summary>
public class BlackHoleCatalog : ScriptableObject
{
    [Serializable]
    public class Item
    {
        public string id;
        public GameObject prefab;
        public float radius;       // footprint radius in world units
        public float height;       // world height
        public float localHeight;  // mesh-space height (used by the fall shader)
        public float lift;         // Y offset so the base sits on the ground
        public int score;
    }

    [Serializable]
    public class Theme
    {
        public string name;
        public Texture2D atlas;
        public int groundStyle;    // 0 city, 1 graveyard, 2 dungeon
        public Item[] items;

        [Header("Ground")]
        public Color colorA;
        public Color colorB;
        public Color colorC;

        [Header("Mood")]
        public Color lightColor;
        public Vector3 lightDir;
        public Color ambientSky;
        public Color ambientGround;
        public Color rim;
        public Color fog;
        public Color border;

        [Header("Hole")]
        public Color holeAccent;
        public Color holeHot;

        [Header("Space")]
        public Color space;
        public Color nebulaA;
        public Color nebulaB;
    }

    [Header("Shaders")]
    public Shader objectShader;
    public Shader groundShader;
    public Shader holeShader;
    public Shader skyShader;
    public Shader particleShader;
    public Shader uiPanelShader;
    public Shader uiTextShader;

    [Header("Audio")]
    public AudioClip menuMusic;
    public AudioClip gameMusic;
    public AudioClip gameOverMusic;
    public AudioClip clickSfx;
    public AudioClip eatSfx;
    public AudioClip coinSfx;
    public AudioClip growSfx;

    public Theme[] themes;

    public static BlackHoleCatalog Load()
    {
        return Resources.Load<BlackHoleCatalog>("BlackHoleCatalog");
    }
}
